FRONTIER_MISSIONS={};FRONTIER_BRIEFINGS={};FRONTIER_PATHS={};FRONTIER_DESCRIPTIONS={};FRONTIER_RULES={};FRONTIER_FIELDS={}
for key,s in STORIES.items():
    acts=s['path']
    assert [len(a) for a in acts]==[5,6],key
    assert len(s['notes'])==11 and len(set(acts[0]+acts[1]))==11,key
    FRONTIER_PATHS[key]=acts
    FRONTIER_MISSIONS[key]={k:s[k] for k in ('title','subtitle','location','story','attack_title','defend_title','attack_action','defend_action','goal','threats','defense','log','beats','crisis_name','crisis_phrase','crisis_intro','switch','win','lose')}
    FRONTIER_MISSIONS[key]['commands']=list(acts[0]+acts[1])
    FRONTIER_MISSIONS[key]['defense']=list(s['defense'])
    FRONTIER_MISSIONS[key]['log']=list(s['log'])
    FRONTIER_BRIEFINGS[key]={k:s[k] for k in ('chapter','opening','hacker','defender','stakes','stageObjectives','outro')}
    FRONTIER_DESCRIPTIONS[key]=dict(zip(acts[0]+acts[1],s['notes']))
    for phrase in s['defense']:
        FRONTIER_DESCRIPTIONS[key][phrase]=f'Protect the team: {phrase}. The defender must interrupt this immediate threat while the explorer recovers the next story objective.'
    FRONTIER_DESCRIPTIONS[key][s['crisis_phrase']]=s['crisis_intro']
    choices={}
    for ident,label,description,phrase,effects,outcome in s['choices']:
        choices[ident]={'label':label,'description':description,'phrase':phrase,'effects':effects,'outcome':outcome}
        FRONTIER_DESCRIPTIONS[key][phrase]=description+' '+outcome
    FRONTIER_RULES[key]={'meter':s['meter'],'direction':'high','initial':19,'hack':6,'defend':-13,'breach':19,'pulse':-13,'warning':67,'warning_text':s['warning_text'],'failure':s['failure'],'intro':s['stakes'],'encounter':s['encounter'],'encounter_intro':s['encounter_intro'],'choices':choices}
    FRONTIER_FIELDS[key]=tuple({'heading':heading,'context':context,'options':tuple({'id':ident,'label':label,'benefit':benefit,'effects':effects,'outcome':outcome} for ident,label,benefit,effects,outcome in options)} for heading,context,options in s['fields'])
